<script setup lang="ts">
import { Head, Link, router } from '@inertiajs/vue3';
import AppShell from '../../Components/AppShell.vue';
import Pagination from '../../Components/Pagination.vue';

type InvoiceLine = { description: string; quantity: number; unitRateMinor: number; totalMinor: number };
type EtimsStatus = { id: number; status: string; receiptNumber: string | null; message: string | null } | null;
type CreditNote = { id: number; number: string; totalMinor: number; issuedOn: string; etims: EtimsStatus };
type Invoice = { id: number; number: string; hireReference: string; customer: string; location: string; issuedOn: string; dueOn: string | null; totalMinor: number; allocatedMinor: number; balanceMinor: number; etims: EtimsStatus; lines: InvoiceLine[]; creditNotes: CreditNote[] };
type CustomOrderInvoice = Omit<Invoice, 'hireReference' | 'lines'> & { orderReference: string; lines: { description: string; quantity: number; totalMinor: number }[] };
const props = defineProps<{ invoices: { data: Invoice[]; links: any[]; from: number | null; to: number | null; total: number }; customOrderInvoices: { data: CustomOrderInvoice[]; links: any[]; from: number | null; to: number | null; total: number }; outstandingMinor: number; canRetryEtims: boolean }>();
const kes = (minor: number) => `KES ${(minor / 100).toLocaleString('en-KE', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const statusLabel = (status: string) => status.replaceAll('_', ' ');
const canQueueAgain = (status: string) => ['configuration_required', 'failed'].includes(status);
const retryEtims = (id: number) => router.post(`/finance/etims/${id}/retry`, {}, { preserveScroll: true });
</script>

<template>
    <Head title="Invoices" />
    <AppShell active="finance">
        <div class="page-heading"><div><h1>Customer invoices</h1><p>Hire charges are invoiced at handover; custom orders are invoiced at completion. Receipts, refunds, and applied deposits reconcile to each balance. Invoice refunds create linked, immutable credit notes.</p></div><Link href="/finance/ledger" class="secondary-link">General ledger</Link></div>
        <section class="panel invoice-summary"><span>Outstanding on current pages</span><strong>{{ kes(outstandingMinor) }}</strong><small>{{ (invoices.total + customOrderInvoices.total).toLocaleString() }} issued invoices</small></section>
        <section class="panel invoice-panel">
            <h2>Hire invoices</h2>
            <div v-if="!invoices.data.length" class="empty-state">No hire invoices have been issued yet.</div>
            <div v-else class="table-wrap"><table><thead><tr><th>Invoice</th><th>Customer / hire</th><th>Location</th><th>Issued</th><th>Due</th><th>Total</th><th>Allocated</th><th>Balance</th></tr></thead><tbody>
                <tr v-for="invoice in invoices.data" :key="invoice.id"><td><a :href="`/finance/invoices/${invoice.id}/pdf`" class="invoice-number">{{ invoice.number }}</a><small v-if="invoice.etims" class="etims-status">eTIMS {{ statusLabel(invoice.etims.status) }}<span v-if="invoice.etims.receiptNumber"> · receipt {{ invoice.etims.receiptNumber }}</span></small><button v-if="canRetryEtims && invoice.etims && canQueueAgain(invoice.etims.status)" class="etims-retry" type="button" @click="retryEtims(invoice.etims.id)">Queue eTIMS retry</button><small v-if="invoice.etims?.message && ['manual_review', 'failed', 'configuration_required', 'historical_review'].includes(invoice.etims.status)" class="etims-message">{{ invoice.etims.message }}</small><details><summary>View {{ invoice.lines.length }} line(s)</summary><ul><li v-for="(line, index) in invoice.lines" :key="index">{{ line.description }} · {{ line.quantity }} × {{ kes(line.unitRateMinor) }} = {{ kes(line.totalMinor) }}</li></ul></details><template v-for="note in invoice.creditNotes" :key="note.id"><a :href="`/finance/credit-notes/${note.id}/pdf`" class="credit-note-link">{{ note.number }} · {{ kes(note.totalMinor) }} · {{ note.issuedOn }}</a><small v-if="note.etims" class="etims-status">eTIMS {{ statusLabel(note.etims.status) }}<span v-if="note.etims.receiptNumber"> · receipt {{ note.etims.receiptNumber }}</span></small><button v-if="canRetryEtims && note.etims && canQueueAgain(note.etims.status)" class="etims-retry" type="button" @click="retryEtims(note.etims.id)">Queue eTIMS retry</button></template></td><td>{{ invoice.customer }}<small class="table-subline">{{ invoice.hireReference }}</small></td><td>{{ invoice.location }}</td><td>{{ invoice.issuedOn }}</td><td>{{ invoice.dueOn ?? '—' }}</td><td>{{ kes(invoice.totalMinor) }}</td><td>{{ kes(invoice.allocatedMinor) }}</td><td><strong :class="invoice.balanceMinor ? 'due' : 'settled'">{{ kes(invoice.balanceMinor) }}</strong></td></tr>
            </tbody></table></div>
            <Pagination v-if="invoices.total > 0" :links="invoices.links" :from="invoices.from" :to="invoices.to" :total="invoices.total" />
        </section>
        <section class="panel invoice-panel">
            <h2>Custom order invoices</h2>
            <div v-if="!customOrderInvoices.data.length" class="empty-state">Completed custom orders will appear here after invoicing.</div>
            <div v-else class="table-wrap"><table><thead><tr><th>Invoice</th><th>Customer / order</th><th>Location</th><th>Issued</th><th>Due</th><th>Total</th><th>Allocated</th><th>Balance</th></tr></thead><tbody>
                <tr v-for="invoice in customOrderInvoices.data" :key="invoice.id"><td><a :href="`/finance/custom-order-invoices/${invoice.id}/pdf`" class="invoice-number">{{ invoice.number }}</a><small v-if="invoice.etims" class="etims-status">eTIMS {{ statusLabel(invoice.etims.status) }}<span v-if="invoice.etims.receiptNumber"> · receipt {{ invoice.etims.receiptNumber }}</span></small><button v-if="canRetryEtims && invoice.etims && canQueueAgain(invoice.etims.status)" class="etims-retry" type="button" @click="retryEtims(invoice.etims.id)">Queue eTIMS retry</button><small v-if="invoice.etims?.message && ['manual_review', 'failed', 'configuration_required', 'historical_review'].includes(invoice.etims.status)" class="etims-message">{{ invoice.etims.message }}</small><details><summary>View {{ invoice.lines.length }} line(s)</summary><ul><li v-for="(line, index) in invoice.lines" :key="index">{{ line.description }} · Qty {{ line.quantity }} · {{ kes(line.totalMinor) }}</li></ul></details><template v-for="note in invoice.creditNotes" :key="note.id"><a :href="`/finance/credit-notes/${note.id}/pdf`" class="credit-note-link">{{ note.number }} · {{ kes(note.totalMinor) }} · {{ note.issuedOn }}</a><small v-if="note.etims" class="etims-status">eTIMS {{ statusLabel(note.etims.status) }}<span v-if="note.etims.receiptNumber"> · receipt {{ note.etims.receiptNumber }}</span></small><button v-if="canRetryEtims && note.etims && canQueueAgain(note.etims.status)" class="etims-retry" type="button" @click="retryEtims(note.etims.id)">Queue eTIMS retry</button></template></td><td>{{ invoice.customer }}<small class="table-subline">{{ invoice.orderReference }}</small></td><td>{{ invoice.location }}</td><td>{{ invoice.issuedOn }}</td><td>{{ invoice.dueOn ?? '—' }}</td><td>{{ kes(invoice.totalMinor) }}</td><td>{{ kes(invoice.allocatedMinor) }}</td><td><strong :class="invoice.balanceMinor ? 'due' : 'settled'">{{ kes(invoice.balanceMinor) }}</strong></td></tr>
            </tbody></table></div>
            <Pagination v-if="customOrderInvoices.total > 0" :links="customOrderInvoices.links" :from="customOrderInvoices.from" :to="customOrderInvoices.to" :total="customOrderInvoices.total" />
        </section>
    </AppShell>
</template>

<style scoped>
.invoice-summary{display:flex;align-items:center;gap:15px;margin-bottom:13px;padding:15px 18px}.invoice-summary span,.invoice-summary small{color:#606874;font-size:11px}.invoice-summary strong{color:#171c26;font-size:21px}.invoice-panel{margin-bottom:13px;padding:16px}.invoice-panel h2{margin:0 0 12px;color:#202633;font-size:13px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{padding:10px 9px;border-bottom:1px solid #eceef1;text-align:left;font-size:10px}th{color:#606874;font-weight:600}td{color:#353c48}td strong{color:#1d2330}.invoice-number{color:#c3272e;font-weight:700;text-decoration:none}.credit-note-link{display:block;margin-top:4px;color:#59687c;font-size:9px;text-decoration:none}.etims-status{color:#805816;font-size:9px;text-transform:capitalize}.etims-message{max-width:240px;white-space:normal!important;color:#7a3135!important}.etims-retry{margin:3px 0;padding:3px 6px;border:1px solid #c3272e;border-radius:4px;background:white;color:#a31f29;font-size:9px;cursor:pointer}td small{display:block;color:#606874;font-size:9px}details{margin-top:4px;color:#7e2630;font-size:9px}details ul{padding-left:16px;white-space:normal;color:#606876}.due{color:#c3272e!important}.settled{color:#12804a!important}.empty-state{padding:32px;text-align:center;color:#606874;font-size:12px}
</style>
